)

type reviewLRSStream struct {
    lrsStream
    response *v3lrspb.LoadStatsResponse
}
func (s reviewLRSStream) Recv() (*v3lrspb.LoadStatsResponse, error) { return s.response, nil }

func TestReviewLRSInvalidDurationDiagnostic(t *testing.T) {
    for name, d := range map[string]*durationpb.Duration{
        "missing": nil,
        "nanos": {Nanos: 1000000000},
        "sign": {Seconds: 1, Nanos: -1},
    } {
        t.Run(name, func(t *testing.T) {
            tr := new(Transport)
            _, _, err := tr.recvFirstLoadStatsResponse(reviewLRSStream{
                response: &v3lrspb.LoadStatsResponse{LoadReportingInterval: d},
            })
            if err == nil { t.Fatal("invalid duration accepted") }
            t.Log(err)
            if strings.Contains(err.Error(), "<nil>") { t.Fatalf("validation reason lost: %v", err) }
        })
    }
}
''')
